// Manually implemented — not generated by codegen.
// CZ_PARTY_MESSAGE (0x0108) has no C struct definition in rAthena; it is a
// variable-length packet parsed manually in clif.cpp via
// clif_process_message with whisperFormat=false.
//
// Wire format: uint16 packetType | uint16 packetLength | "Name : Message\0"
// Identical to PublicChat wire layout with a different packet ID.

package encode

import (
	"encoding/binary"

	"github.com/lenaxia/rathena-client/pkg/send"
)

// EncodePartyChat encodes a PartyChat packet (CZ_PARTY_MESSAGE / 0x0108).
// Returns a variable-length byte slice.
func EncodePartyChat(req send.PartyChat, _ uint32) []byte {
	const pktID uint16 = 0x0108
	text := req.Name + " : " + req.Message + "\x00"
	totalLen := 4 + len(text)
	buf := make([]byte, totalLen)
	binary.LittleEndian.PutUint16(buf[0:], pktID)
	binary.LittleEndian.PutUint16(buf[2:], uint16(totalLen))
	copy(buf[4:], text)
	return buf
}
